import{_t as e,it as t,n,rt as r}from"./chunks/framework.yS8CksER.js";var i=JSON.parse(`{"title":"Catalogs","description":"","frontmatter":{"title":"Catalogs"},"headers":[],"relativePath":"api/reference/catalogs.md","filePath":"api/reference/catalogs.md"}`),a={name:`api/reference/catalogs.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to “Catalogs”">​</a></h1><div><p>Operations of the tag <strong>Catalogs</strong> implemented in this release. Generated from <code>api/openapi.yaml</code>; planned operations are not listed.</p><h2 id="listCatalogs" tabindex="-1">Catalog overview (US-046, SCR-020) <a class="header-anchor" href="#listCatalogs" aria-label="Permalink to “Catalog overview (US-046, SCR-020)”">​</a></h2><p><code>GET /catalogs</code> · <code>listCatalogs</code></p><p>All catalogs with scope <code>instance</code> and the caller&#39;s own catalogs with scope <code>personal</code>, ordered by name (case-insensitive).</p><p><strong>Access</strong>: permission <code>entity:read</code></p><h3 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Visible catalogs</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr></tbody></table><h2 id="createCatalog" tabindex="-1">Create a catalog (US-046, REQ-043) <a class="header-anchor" href="#createCatalog" aria-label="Permalink to “Create a catalog (US-046, REQ-043)”">​</a></h2><p><code>POST /catalogs</code> · <code>createCatalog</code></p><p>Creates a catalog without columns, joins, saved filters and saved views. A catalog with scope <code>instance</code> additionally requires <code>catalog:manage</code> (ADR-032 §3); a catalog with scope <code>personal</code> is visible only to its creator. The name is unique within the instance across both scopes, compared case-insensitively after trimming, and stored trimmed. Writes the audit event <code>catalog.created</code>.</p><p><strong>Access</strong>: permission <code>entity:read</code>; additionally <code>catalog:manage</code> when body field scope is &#39;instance&#39;</p><h3 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: CatalogCreate</li></ul><h3 id="responses-1" tabindex="-1">Responses <a class="header-anchor" href="#responses-1" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>201</td><td>Catalog created</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Invalid input (problem type <code>urn:oea:problem:validation-failed</code>, e.g. an unknown primary metatype) or a name that is already taken (problem type <code>urn:oea:problem:catalog-name-taken</code>, detail &quot;A catalog with this name already exists&quot;); <code>invalidFields</code> names the rejected fields. Nothing is stored.</td><td><code>urn:oea:problem:validation-failed</code>, <code>urn:oea:problem:catalog-name-taken</code></td></tr></tbody></table><h2 id="getCatalog" tabindex="-1">Read a catalog (US-046) <a class="header-anchor" href="#getCatalog" aria-label="Permalink to “Read a catalog (US-046)”">​</a></h2><p><code>GET /catalogs/{id}</code> · <code>getCatalog</code></p><p>A personal catalog of another person is answered with 404, like a catalog that does not exist (ADR-032 §8 L3).</p><p><strong>Access</strong>: permission <code>entity:read</code></p><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>string (uuid)</td><td>–</td></tr></tbody></table><h3 id="responses-2" tabindex="-1">Responses <a class="header-anchor" href="#responses-2" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>The catalog</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr></tbody></table><h2 id="queryCatalog" tabindex="-1">Query a catalog (US-049, REQ-046, SCR-020) <a class="header-anchor" href="#queryCatalog" aria-label="Permalink to “Query a catalog (US-049, REQ-046, SCR-020)”">​</a></h2><p><code>GET /catalogs/{id}/query</code> · <code>queryCatalog</code></p><p>One page of rows: the active entities of the catalog&#39;s primary metatype with the values of the catalog&#39;s columns. Until columns can be configured (US-047), the columns are <code>name</code> and, if the primary metatype maps a property named <code>Status</code> with visibility <code>public</code>, that property. Only properties with visibility <code>public</code> appear (REQ-160 follows). Soft-deleted entities are not returned (ADR-019).</p><p><code>sort</code> accepts exactly one <code>{column}:{asc|desc}</code> pair whose column is a key of <code>columns</code>. Without <code>sort</code> the rows are ordered by name ascending; rows without a value in the sort column come last. Sorting applies before paging; a page beyond the last one answers with no rows. A personal catalog of another person is answered with 404, like a catalog that does not exist (ADR-032 §8 L3).</p><p><strong>Access</strong>: permission <code>entity:read</code></p><h3 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>string (uuid)</td><td>–</td></tr><tr><td><code>page</code></td><td>query</td><td>no</td><td>integer</td><td>–</td></tr><tr><td><code>pageSize</code></td><td>query</td><td>no</td><td>integer</td><td>–</td></tr><tr><td><code>sort</code></td><td>query</td><td>no</td><td>string</td><td><code>{field}:{asc|desc}</code>, multiple comma-separated</td></tr></tbody></table><h3 id="responses-3" tabindex="-1">Responses <a class="header-anchor" href="#responses-3" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>One page of catalog rows</td><td>–</td></tr><tr><td>400</td><td>Invalid paging or sort parameters (problem type <code>urn:oea:problem:validation-failed</code>), e.g. an unknown sort column, several sort pairs or a page size above 200; <code>invalidFields</code> names the rejected parameters.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td>–</td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};